{"content": "import { Suspense } from 'react'
import { cookies, headers } from 'next/headers'
import { getProjectTotals } from '@/lib/projects'

export default function DashboardPage() {
  return (
    <main>
      <h1>Workspace</h1>

      {/* Shared project totals — cached, so they prerender into the static shell
          and stay reusable across every member's request. */}
      <ProjectTotals />

      {/* Member-specific data reads cookies and headers, which only exist at
          request time, so it streams in behind this boundary. The frame above
          stays visible while this content loads. */}
      <Suspense fallback={<MemberCardFallback />}>
        <MemberCard />
      </Suspense>
    </main>
  )
}

async function ProjectTotals() {
  const totals = await getProjectTotals()

  return (
    <section>
      <h2>Project totals</h2>
      <p>{totals.active} active projects</p>
      <p>{totals.archived} archived projects</p>
    </section>
  )
}

async function MemberCard() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const member = cookieStore.get('member')?.value ?? 'Guest'
  const team = cookieStore.get('team')?.value ?? 'Community'
  const region = requestHeaders.get('x-region') ?? 'global'

  return (
    <section>
      <h2>Your workspace</h2>
      <p>Welcome, {member}</p>
      <p>Team: {team}</p>
      <p>Region: {region}</p>
    </section>
  )
}

function MemberCardFallback() {
  return (
    <section aria-busy="true">
      <h2>Your workspace</h2>
      <p>Loading your details…</p>
    </section>
  )
}
